import { randomUUID } from 'node:crypto';
import { createRequire } from 'node:module';
import type { Express, RequestHandler, Response } from 'express';
import type { PrismaClient, UserRole } from '@prisma/client';
import { z } from 'zod';
import { runApprovedITCodingWorker } from './it-coding-worker.js';
import { getITSpecialistGateState, getITSpecialistKnowledgeContext, itSpecialistKnowledgeStatus, mergeITSpecialistPullRequest, syncITSpecialistKnowledge, verifyITSpecialistProductionCommit } from './it-specialist-knowledge.js';

const require=createRequire(import.meta.url);
const nodemailer=require('nodemailer') as typeof import('nodemailer');

type AuthContext={userId:string;organizationId:string;role:UserRole;email?:string;legalEntityId?:string|null};
type Dependencies={app:Express;prisma:PrismaClient;authOf:(response:Response)=>AuthContext;requireRoles:(...roles:UserRole[])=>RequestHandler;adminRoles:readonly UserRole[]};
type Json=Record<string,unknown>;
type QueueRow={id:string;organizationId:string;ticketId:string;ticketNumber:string;employeeId:string;conversationId:string|null;phase:string;approvalId:string|null;prNumber:number|null;prUrl:string|null;headSha:string|null;mergeSha:string|null;classification:string;diagnosis:string;ownerNote:string;repairAttempts:number;phaseStartedAt:Date|string;lastITMessageAt:Date|string|null;lastEmployeeMessageAt:Date|string|null};

type TriageResult={classification:'SUPPORT_GUIDANCE'|'RESOLVED_CONFIRMATION'|'ESTABLISHED_OPERATION_REPAIR'|'MAJOR_CHANGE'|'RESTRICTED_HUMAN';confidence:number;diagnosis:string;employeeMessage:string;needsEmployeeInput:boolean;employeeQuestion:string;engineeringNeed:'NO_ENGINEERING_CHANGE'|'CODE_PATCH'|'CONFIG_REPAIR'|'DEPLOYMENT_REPAIR'|'DATA_REPAIR';risk:'LOW'|'MEDIUM'|'HIGH'|'CRITICAL';summary:string;request:string;target:string;reason:string;visualGuide?:{title?:string;steps?:Array<{label?:string;instruction?:string;target?:string}>}};

const clean=(value:unknown,max=12000)=>String(value??'').trim().slice(0,max);
const obj=(value:unknown):Json=>{if(value&&typeof value==='object'&&!Array.isArray(value))return value as Json;if(typeof value==='string'){try{const parsed=JSON.parse(value);return parsed&&typeof parsed==='object'&&!Array.isArray(parsed)?parsed:{}}catch{return{}}}return{}};
const boolEnv=(name:string)=>String(process.env[name]||'').trim().toLowerCase()==='true';
const enabled=()=>boolEnv('IT_SPECIALIST_ENABLED');
const autoProduction=()=>boolEnv('IT_SPECIALIST_AUTO_PRODUCTION_ENABLED');
const model=()=>clean(process.env.IT_SPECIALIST_MODEL||process.env.SIA_OPENAI_MODEL||'gpt-5.6-terra',120);
const openAIKey=()=>process.env.OPENAI_API_KEY?.trim()||'';
const httpError=(status:number,message:string)=>Object.assign(new Error(message),{status});
const redact=(value:string)=>clean(value,12000).replace(/\bBearer\s+[A-Za-z0-9._~-]{12,}\b/gi,'Bearer [REDACTED_TOKEN]').replace(/\b(api[_ -]?key|access[_ -]?token|secret|password|mfa|otp)\s*[:=]\s*[^\s,;]+/gi,'$1=[REDACTED]').replace(/\bsk-[A-Za-z0-9_-]{12,}\b/g,'[REDACTED_KEY]').replace(/\b\d{3}-\d{2}-\d{4}\b/g,'[REDACTED_SSN]');
const ticketPattern=/\bIT-\d{8}-[A-Z0-9]{6}\b/i;
const uuidPattern=/\b[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\b/i;
const decisionSchema=z.object({ticketNumber:z.string().trim().min(6).max(120),decision:z.enum(['APPROVE','MODIFY','DECLINE']),note:z.string().trim().max(4000).optional().default('')});

const ticketNumber=()=>`IT-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${randomUUID().replace(/-/g,'').slice(0,6).toUpperCase()}`;

export async function ensureITSpecialistSchema(prisma:PrismaClient){
  await prisma.$executeRawUnsafe(`ALTER TABLE "EmployeeSupportRequest" ADD COLUMN IF NOT EXISTS "ticketNumber" TEXT`);
  await prisma.$executeRawUnsafe(`CREATE UNIQUE INDEX IF NOT EXISTS "EmployeeSupportRequest_ticketNumber_uq" ON "EmployeeSupportRequest"("ticketNumber") WHERE "ticketNumber" IS NOT NULL`);
  await prisma.$executeRawUnsafe(`CREATE TABLE IF NOT EXISTS "ITTicketConversationBridge" ("ticketId" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"ticketNumber" TEXT NOT NULL,"employeeId" TEXT NOT NULL,"conversationId" TEXT,"state" TEXT NOT NULL DEFAULT 'OPEN',"lastEmployeeMessageAt" TIMESTAMPTZ,"lastITMessageAt" TIMESTAMPTZ,"heartbeatAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),"createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
  await prisma.$executeRawUnsafe(`CREATE UNIQUE INDEX IF NOT EXISTS "ITTicketConversationBridge_number_uq" ON "ITTicketConversationBridge"("organizationId","ticketNumber")`);
  await prisma.$executeRawUnsafe(`CREATE INDEX IF NOT EXISTS "ITTicketConversationBridge_conversation_idx" ON "ITTicketConversationBridge"("organizationId","conversationId","state")`);
  await prisma.$executeRawUnsafe(`CREATE TABLE IF NOT EXISTS "ITSpecialistMessage" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"ticketId" TEXT NOT NULL,"ticketNumber" TEXT NOT NULL,"conversationId" TEXT,"employeeId" TEXT NOT NULL,"direction" TEXT NOT NULL,"content" TEXT NOT NULL,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
  await prisma.$executeRawUnsafe(`CREATE INDEX IF NOT EXISTS "ITSpecialistMessage_ticket_idx" ON "ITSpecialistMessage"("organizationId","ticketId","createdAt" DESC)`);
  await prisma.$executeRawUnsafe(`CREATE TABLE IF NOT EXISTS "ITSpecialistQueue" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"ticketId" TEXT NOT NULL,"ticketNumber" TEXT NOT NULL,"employeeId" TEXT NOT NULL,"conversationId" TEXT,"phase" TEXT NOT NULL DEFAULT 'PENDING',"classification" TEXT NOT NULL DEFAULT '',"diagnosis" TEXT NOT NULL DEFAULT '',"approvalId" TEXT,"prNumber" INTEGER,"prUrl" TEXT,"headSha" TEXT,"mergeSha" TEXT,"ownerNote" TEXT NOT NULL DEFAULT '',"repairAttempts" INTEGER NOT NULL DEFAULT 0,"nextRunAt" TIMESTAMPTZ,"leaseUntil" TIMESTAMPTZ,"phaseStartedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),"lastEmployeeMessageAt" TIMESTAMPTZ,"lastITMessageAt" TIMESTAMPTZ,"lastError" TEXT NOT NULL DEFAULT '',"createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
  await prisma.$executeRawUnsafe(`CREATE UNIQUE INDEX IF NOT EXISTS "ITSpecialistQueue_ticket_uq" ON "ITSpecialistQueue"("organizationId","ticketId")`);
  await prisma.$executeRawUnsafe(`CREATE INDEX IF NOT EXISTS "ITSpecialistQueue_due_idx" ON "ITSpecialistQueue"("phase","nextRunAt","leaseUntil")`);
  await prisma.$executeRawUnsafe(`CREATE TABLE IF NOT EXISTS "ITVisualGuide" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"ticketId" TEXT NOT NULL,"ticketNumber" TEXT NOT NULL,"employeeId" TEXT NOT NULL,"title" TEXT NOT NULL,"steps" JSONB NOT NULL DEFAULT '[]'::jsonb,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
  await prisma.$executeRawUnsafe(`CREATE INDEX IF NOT EXISTS "ITVisualGuide_ticket_idx" ON "ITVisualGuide"("organizationId","ticketId","createdAt" DESC)`);
  await prisma.$executeRawUnsafe(`CREATE TABLE IF NOT EXISTS "ITSpecialistProductionRun" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"ticketId" TEXT NOT NULL,"ticketNumber" TEXT NOT NULL,"prNumber" INTEGER,"headSha" TEXT,"mergeSha" TEXT,"status" TEXT NOT NULL,"gateEvidence" JSONB NOT NULL DEFAULT '{}'::jsonb,"productionEvidence" JSONB NOT NULL DEFAULT '{}'::jsonb,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
}

async function ticketNumberFor(prisma:PrismaClient,organizationId:string,ticketId:string){
  const rows=await prisma.$queryRawUnsafe<Array<{ticketNumber:string|null}>>(`SELECT "ticketNumber" FROM "EmployeeSupportRequest" WHERE "organizationId"=$1 AND "id"=$2 LIMIT 1`,organizationId,ticketId);if(!rows[0])throw httpError(404,'Employee IT ticket was not found');
  if(rows[0].ticketNumber)return rows[0].ticketNumber;const number=ticketNumber();await prisma.$executeRawUnsafe(`UPDATE "EmployeeSupportRequest" SET "ticketNumber"=$1,"updatedAt"=NOW() WHERE "organizationId"=$2 AND "id"=$3 AND "ticketNumber" IS NULL`,number,organizationId,ticketId);const verify=await prisma.$queryRawUnsafe<Array<{ticketNumber:string}>>(`SELECT "ticketNumber" FROM "EmployeeSupportRequest" WHERE "organizationId"=$1 AND "id"=$2`,organizationId,ticketId);return verify[0]?.ticketNumber||number;
}

export async function enqueueITSpecialistTicket(prisma:PrismaClient,input:{organizationId:string;ticketId:string;employeeId:string;conversationId?:string|null}){
  await ensureITSpecialistSchema(prisma);const number=await ticketNumberFor(prisma,input.organizationId,input.ticketId);
  await prisma.$executeRawUnsafe(`INSERT INTO "ITTicketConversationBridge" ("ticketId","organizationId","ticketNumber","employeeId","conversationId","lastEmployeeMessageAt") VALUES ($1,$2,$3,$4,$5,NOW()) ON CONFLICT ("ticketId") DO UPDATE SET "conversationId"=COALESCE(EXCLUDED."conversationId","ITTicketConversationBridge"."conversationId"),"lastEmployeeMessageAt"=NOW(),"updatedAt"=NOW()`,input.ticketId,input.organizationId,number,input.employeeId,input.conversationId??null);
  await prisma.$executeRawUnsafe(`INSERT INTO "ITSpecialistQueue" ("id","organizationId","ticketId","ticketNumber","employeeId","conversationId","phase","nextRunAt","lastEmployeeMessageAt") VALUES ($1,$2,$3,$4,$5,$6,'PENDING',NOW(),NOW()) ON CONFLICT ("organizationId","ticketId") DO UPDATE SET "conversationId"=COALESCE(EXCLUDED."conversationId","ITSpecialistQueue"."conversationId"),"phase"=CASE WHEN "ITSpecialistQueue"."phase" IN ('RESOLVED','DECLINED') THEN "ITSpecialistQueue"."phase" ELSE 'PENDING' END,"nextRunAt"=CASE WHEN "ITSpecialistQueue"."phase" IN ('RESOLVED','DECLINED') THEN "ITSpecialistQueue"."nextRunAt" ELSE NOW() END,"lastEmployeeMessageAt"=NOW(),"updatedAt"=NOW()`,randomUUID(),input.organizationId,input.ticketId,number,input.employeeId,input.conversationId??null);
  return{ticketId:input.ticketId,ticketNumber:number,status:'OPEN'};
}

async function findTicketForMessage(prisma:PrismaClient,input:{organizationId:string;employeeId:string;conversationId?:string|null;message:string}){
  const explicit=(input.message.match(ticketPattern)?.[0]||input.message.match(uuidPattern)?.[0]||'').trim();
  if(explicit){const rows=await prisma.$queryRawUnsafe<any[]>(`SELECT q.* FROM "ITSpecialistQueue" q WHERE q."organizationId"=$1 AND q."employeeId"=$2 AND (LOWER(q."ticketNumber")=LOWER($3) OR q."ticketId"=$3) ORDER BY q."updatedAt" DESC LIMIT 1`,input.organizationId,input.employeeId,explicit);if(rows[0])return rows[0] as QueueRow}
  if(input.conversationId){const rows=await prisma.$queryRawUnsafe<any[]>(`SELECT q.* FROM "ITSpecialistQueue" q WHERE q."organizationId"=$1 AND q."employeeId"=$2 AND q."conversationId"=$3 AND q."phase" NOT IN ('RESOLVED','DECLINED') ORDER BY q."updatedAt" DESC LIMIT 1`,input.organizationId,input.employeeId,input.conversationId);if(rows[0])return rows[0] as QueueRow}
  return null;
}

export async function relaySiaMessageToITSpecialist(prisma:PrismaClient,input:{organizationId:string;employeeId:string;conversationId?:string|null;message:string}){
  await ensureITSpecialistSchema(prisma);const ticket=await findTicketForMessage(prisma,input);if(!ticket)return null;const content=redact(input.message);
  await prisma.$executeRawUnsafe(`INSERT INTO "ITSpecialistMessage" ("id","organizationId","ticketId","ticketNumber","conversationId","employeeId","direction","content") VALUES ($1,$2,$3,$4,$5,$6,'EMPLOYEE_TO_IT',$7)`,randomUUID(),input.organizationId,ticket.ticketId,ticket.ticketNumber,input.conversationId??ticket.conversationId,input.employeeId,content);
  await prisma.$executeRawUnsafe(`UPDATE "ITTicketConversationBridge" SET "conversationId"=COALESCE($1,"conversationId"),"lastEmployeeMessageAt"=NOW(),"heartbeatAt"=NOW(),"updatedAt"=NOW() WHERE "organizationId"=$2 AND "ticketId"=$3`,input.conversationId??null,input.organizationId,ticket.ticketId);
  await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "conversationId"=COALESCE($1,"conversationId"),"lastEmployeeMessageAt"=NOW(),"phase"=CASE WHEN "phase" IN ('WAITING_EMPLOYEE','FOLLOW_UP') THEN 'PENDING' ELSE "phase" END,"nextRunAt"=CASE WHEN "phase" IN ('WAITING_EMPLOYEE','FOLLOW_UP') THEN NOW() ELSE "nextRunAt" END,"updatedAt"=NOW() WHERE "organizationId"=$2 AND "ticketId"=$3`,input.conversationId??null,input.organizationId,ticket.ticketId);
  return{ticketId:ticket.ticketId,ticketNumber:ticket.ticketNumber,phase:ticket.phase};
}

export async function loadITSpecialistSiaContext(prisma:PrismaClient,input:{organizationId:string;employeeId:string;conversationId?:string|null;message:string}){
  await ensureITSpecialistSchema(prisma);const ticket=await findTicketForMessage(prisma,input);if(!ticket)return[] as string[];
  const [request,updates,approval]=await Promise.all([
    prisma.$queryRawUnsafe<any[]>(`SELECT "subject","category","priority","status","resolution","updatedAt" FROM "EmployeeSupportRequest" WHERE "organizationId"=$1 AND "id"=$2 LIMIT 1`,input.organizationId,ticket.ticketId),
    prisma.$queryRawUnsafe<any[]>(`SELECT "message","status","createdAt" FROM "ITEmployeeUpdate" WHERE "organizationId"=$1 AND "ticketId"=$2 ORDER BY "createdAt" DESC LIMIT 5`,input.organizationId,ticket.ticketId).catch(()=>[]),
    ticket.approvalId?prisma.$queryRawUnsafe<any[]>(`SELECT "status","summary","decisionNote","updatedAt" FROM "ITRemediationApproval" WHERE "organizationId"=$1 AND "id"=$2 LIMIT 1`,input.organizationId,ticket.approvalId):Promise.resolve([]),
  ]);
  return[
    `activeItTicketNumber: ${ticket.ticketNumber}`,
    `activeItTicketPhase: ${ticket.phase}`,
    `activeItTicketClassification: ${ticket.classification||'PENDING_TRIAGE'}`,
    `activeItTicketSubject: ${redact(request[0]?.subject||'')}`,
    `activeItTicketStatus: ${request[0]?.status||'OPEN'}`,
    `activeItTicketDiagnosis: ${redact(ticket.diagnosis||'')}`,
    `activeItTicketOwnerApproval: ${approval[0]?.status||'NOT_REQUIRED_OR_NOT_CREATED'}`,
    ...updates.reverse().map((row:any)=>`activeItTicketUpdate: ${redact(row.message||'')}`),
    'activeItTicketInstruction: Continue helping the employee in this same SIA conversation. Treat the IT Specialist updates as trusted ticket state. Always include the ticket number when discussing this incident. If the employee supplies new troubleshooting evidence or says whether a proposed fix worked, relay that information to the active ticket instead of starting over.',
  ];
}

async function systemActor(prisma:PrismaClient,organizationId:string,fallback:string){const rows=await prisma.$queryRawUnsafe<Array<{id:string}>>(`SELECT "id" FROM "User" WHERE "organizationId"=$1 AND "role"::text IN ('ADMINISTRATOR','CEO') ORDER BY CASE "role"::text WHEN 'ADMINISTRATOR' THEN 1 ELSE 2 END,"createdAt" ASC LIMIT 1`,organizationId).catch(()=>[]);return rows[0]?.id||fallback}

async function postEmployeeUpdate(prisma:PrismaClient,ticket:QueueRow,message:string,status:string){
  const text=redact(message),conversationId=ticket.conversationId;const actor=await systemActor(prisma,ticket.organizationId,ticket.employeeId);
  await prisma.$executeRawUnsafe(`INSERT INTO "ITEmployeeUpdate" ("id","organizationId","ticketId","conversationId","employeeId","message","pushTitle","pushBody","status") VALUES ($1,$2,$3,$4,$5,$6,'Sulandra IT update',$7,$8)`,randomUUID(),ticket.organizationId,ticket.ticketId,conversationId||'',ticket.employeeId,text,clean(`${ticket.ticketNumber}: ${text}`,1000),status).catch(()=>{});
  await prisma.$executeRawUnsafe(`INSERT INTO "ITSpecialistMessage" ("id","organizationId","ticketId","ticketNumber","conversationId","employeeId","direction","content") VALUES ($1,$2,$3,$4,$5,$6,'IT_TO_EMPLOYEE',$7)`,randomUUID(),ticket.organizationId,ticket.ticketId,ticket.ticketNumber,conversationId,ticket.employeeId,text);
  if(conversationId){const content=`**Sulandra IT — ${ticket.ticketNumber}**\n\n${text}`;await prisma.$executeRawUnsafe(`INSERT INTO "SIAMessage" ("id","organizationId","conversationId","userId","role","content","model") VALUES ($1,$2,$3,$4,'assistant',$5,'sulandra-it-specialist')`,randomUUID(),ticket.organizationId,conversationId,ticket.employeeId,content).catch(()=>{});await prisma.$executeRawUnsafe(`UPDATE "SIAConversation" SET "updatedAt"=NOW() WHERE "organizationId"=$1 AND "id"=$2`,ticket.organizationId,conversationId).catch(()=>{})}
  await prisma.$executeRawUnsafe(`INSERT INTO "EmployeeNotification" ("id","organizationId","employeeId","title","message","category","actionUrl","createdById") VALUES ($1,$2,$3,$4,$5,'WORKFLOW','/sia.html',$6)`,randomUUID(),ticket.organizationId,ticket.employeeId,`Sulandra IT ${ticket.ticketNumber}`,text,actor).catch(()=>{});
  await prisma.$executeRawUnsafe(`UPDATE "ITTicketConversationBridge" SET "lastITMessageAt"=NOW(),"heartbeatAt"=NOW(),"updatedAt"=NOW() WHERE "organizationId"=$1 AND "ticketId"=$2`,ticket.organizationId,ticket.ticketId).catch(()=>{});
  await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "lastITMessageAt"=NOW(),"updatedAt"=NOW() WHERE "organizationId"=$1 AND "ticketId"=$2`,ticket.organizationId,ticket.ticketId).catch(()=>{});
}

async function createVisualGuide(prisma:PrismaClient,ticket:QueueRow,guide:TriageResult['visualGuide']){
  const steps=Array.isArray(guide?.steps)?guide!.steps!.slice(0,8).map((step,index)=>({number:index+1,label:clean(step.label||`Step ${index+1}`,100),instruction:clean(step.instruction,1000),target:clean(step.target,200)})):[];
  if(!steps.length)return null;const id=randomUUID(),title=clean(guide?.title||`Help for ${ticket.ticketNumber}`,220);await prisma.$executeRawUnsafe(`INSERT INTO "ITVisualGuide" ("id","organizationId","ticketId","ticketNumber","employeeId","title","steps") VALUES ($1,$2,$3,$4,$5,$6,$7::jsonb)`,id,ticket.organizationId,ticket.ticketId,ticket.ticketNumber,ticket.employeeId,title,JSON.stringify(steps));return{id,title,url:`/it-guide.html?guide=${encodeURIComponent(id)}&ticket=${encodeURIComponent(ticket.ticketNumber)}`}
}

async function openAIJson(instructions:string,input:string){
  const key=openAIKey();if(!key)throw httpError(503,'OpenAI is not configured for the IT Specialist');const response=await fetch('https://api.openai.com/v1/responses',{method:'POST',headers:{Authorization:`Bearer ${key}`,'Content-Type':'application/json'},body:JSON.stringify({model:model(),instructions,input,max_output_tokens:3500}),signal:AbortSignal.timeout(120000)});const payload=await response.json() as any;if(!response.ok)throw httpError(502,clean(payload?.error?.message||`IT Specialist AI request failed (${response.status})`,900));const chunks:string[]=[];for(const item of payload.output||[])if(item?.type==='message')for(const part of item?.content||[])if(part?.type==='output_text'&&part?.text)chunks.push(part.text);const text=clean(chunks.join('\n')||payload.output_text,50000).replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');const start=text.indexOf('{'),end=text.lastIndexOf('}');if(start<0||end<start)throw httpError(502,'IT Specialist AI returned no JSON object');try{return JSON.parse(text.slice(start,end+1)) as Json}catch{throw httpError(502,'IT Specialist AI returned invalid JSON')}}

async function triageTicket(prisma:PrismaClient,ticket:QueueRow):Promise<TriageResult>{
  const [requests,messages,evidence]=await Promise.all([
    prisma.$queryRawUnsafe<any[]>(`SELECT "subject","description","category","priority","status","resolution" FROM "EmployeeSupportRequest" WHERE "organizationId"=$1 AND "id"=$2 LIMIT 1`,ticket.organizationId,ticket.ticketId),
    prisma.$queryRawUnsafe<any[]>(`SELECT "direction","content","createdAt" FROM "ITSpecialistMessage" WHERE "organizationId"=$1 AND "ticketId"=$2 ORDER BY "createdAt" DESC LIMIT 20`,ticket.organizationId,ticket.ticketId),
    prisma.$queryRawUnsafe<any[]>(`SELECT "source","application","page","workflow","step","action","outcome","statusCode","correlationId","detail","createdAt" FROM "ITDiagnosticEvidence" WHERE "organizationId"=$1 AND "ticketId"=$2 ORDER BY "createdAt" DESC LIMIT 30`,ticket.organizationId,ticket.ticketId).catch(()=>[]),
  ]);const request=requests[0];if(!request)throw httpError(404,'Employee IT ticket was not found');
  const knowledge=await getITSpecialistKnowledgeContext(prisma,`${request.subject} ${request.description} ${messages.map((row:any)=>row.content).join(' ')} ${ticket.ownerNote}`);
  const raw=await openAIJson(`You are the Sulandra Health autonomous IT Specialist triage engine. Return JSON only. Your job is to keep employee support moving until the issue is solved while preserving security, privacy, clinical safety, payroll integrity, tenant isolation, and production reliability.

Classify exactly one of:
SUPPORT_GUIDANCE: ordinary navigation/browser/account/device/workflow help that does not need code/config/data mutation.
RESOLVED_CONFIRMATION: the employee's latest message clearly confirms the active ticket is fixed.
ESTABLISHED_OPERATION_REPAIR: an already-approved Sulandra behavior is broken/regressed and can be restored without inventing functionality. This is allowed only when current code/contracts or supplied merged PR/release history establish the intended behavior; the repair is reversible; risk is LOW or MEDIUM; and it does not change permissions, authentication policy, security policy, secrets, credentials, destructive data, clinical records/decisions, payroll/payment decisions, cross-tenant access, database meaning, or new integration behavior. If evidence is uncertain, do NOT use this class.
MAJOR_CHANGE: new capability, materially changed behavior/business rule, permissions/auth/security, schema/data meaning, external integration behavior, production architecture, destructive operation, or any uncertain change that should require owner approval.
RESTRICTED_HUMAN: a request that would require handling a password/MFA secret, patient-identifying clinical content, payment authorization, unsafe surveillance, or another action the IT agent should not perform autonomously.

For SUPPORT_GUIDANCE, produce concise employeeMessage and a visualGuide with 2-6 steps. Each step needs label, instruction, and target (the button/menu/page to click). For ESTABLISHED_OPERATION_REPAIR or MAJOR_CHANGE, provide engineeringNeed, summary, request, target, reason, and risk. Ask for employee input only when one specific missing fact prevents safe progress. Never say a repair happened unless trusted execution evidence says so.

JSON schema: {"classification":"...","confidence":0.0,"diagnosis":"...","employeeMessage":"...","needsEmployeeInput":false,"employeeQuestion":"","engineeringNeed":"NO_ENGINEERING_CHANGE|CODE_PATCH|CONFIG_REPAIR|DEPLOYMENT_REPAIR|DATA_REPAIR","risk":"LOW|MEDIUM|HIGH|CRITICAL","summary":"...","request":"...","target":"...","reason":"...","visualGuide":{"title":"...","steps":[{"label":"...","instruction":"...","target":"..."}]}}`,
    `TICKET ${ticket.ticketNumber}\nSUBJECT: ${redact(request.subject||'')}\nDESCRIPTION: ${redact(request.description||'')}\nCATEGORY: ${request.category}\nPRIORITY: ${request.priority}\nCURRENT PHASE: ${ticket.phase}\nOWNER NOTE: ${redact(ticket.ownerNote||'')}\n\nRECENT EMPLOYEE/IT MESSAGES:\n${messages.reverse().map((row:any)=>`${row.direction}: ${redact(row.content||'')}`).join('\n')}\n\nSANITIZED EVIDENCE:\n${evidence.map((row:any)=>JSON.stringify({...row,detail:redact(row.detail||'')})).join('\n')}\n\nCURRENT REPOSITORY HEAD: ${knowledge.headSha}\nREPOSITORY AREAS: ${JSON.stringify(knowledge.areas)}\nRELEVANT CURRENT FILES:\n${knowledge.fileMatches.slice(0,80).map((item:any)=>`${item.area}: ${item.path}`).join('\n')}\n\nRELEVANT APPROVED/MERGED WORK (${knowledge.approvedEvidenceCount} matches):\n${knowledge.approvedWorkMatches.map((item:any)=>item.kind==='MERGED_PR'?`PR #${item.number}: ${item.title} | ${clean(item.body,800)}`:`COMMIT ${item.sha}: ${clean(item.message,800)}`).join('\n')}`);
  const classification=clean(raw.classification,80) as TriageResult['classification'];const risk=clean(raw.risk,20) as TriageResult['risk'];const engineeringNeed=clean(raw.engineeringNeed,40) as TriageResult['engineeringNeed'];
  if(!['SUPPORT_GUIDANCE','RESOLVED_CONFIRMATION','ESTABLISHED_OPERATION_REPAIR','MAJOR_CHANGE','RESTRICTED_HUMAN'].includes(classification))throw httpError(502,'IT Specialist returned an invalid classification');
  if(classification==='ESTABLISHED_OPERATION_REPAIR'&&(knowledge.approvedEvidenceCount<1||!['LOW','MEDIUM'].includes(risk)||['DATA_REPAIR'].includes(engineeringNeed)))return{classification:'MAJOR_CHANGE',confidence:Number(raw.confidence||0),diagnosis:clean(raw.diagnosis,4000),employeeMessage:clean(raw.employeeMessage,3000),needsEmployeeInput:Boolean(raw.needsEmployeeInput),employeeQuestion:clean(raw.employeeQuestion,1500),engineeringNeed,risk:['LOW','MEDIUM','HIGH','CRITICAL'].includes(risk)?risk:'HIGH',summary:clean(raw.summary,500),request:clean(raw.request,8000),target:clean(raw.target,1500),reason:`Escalated because the autonomous established-repair safety contract was not fully proven. ${clean(raw.reason,3000)}`,visualGuide:raw.visualGuide as any};
  return{classification,confidence:Number(raw.confidence||0),diagnosis:clean(raw.diagnosis,4000),employeeMessage:clean(raw.employeeMessage,3000),needsEmployeeInput:Boolean(raw.needsEmployeeInput),employeeQuestion:clean(raw.employeeQuestion,1500),engineeringNeed:['NO_ENGINEERING_CHANGE','CODE_PATCH','CONFIG_REPAIR','DEPLOYMENT_REPAIR','DATA_REPAIR'].includes(engineeringNeed)?engineeringNeed:'NO_ENGINEERING_CHANGE',risk:['LOW','MEDIUM','HIGH','CRITICAL'].includes(risk)?risk:'HIGH',summary:clean(raw.summary,500),request:clean(raw.request,8000),target:clean(raw.target,1500),reason:clean(raw.reason,3000),visualGuide:raw.visualGuide as any};
}

async function ownerRecipients(prisma:PrismaClient,organizationId:string){const rows=await prisma.$queryRawUnsafe<Array<{email:string|null}>>(`SELECT DISTINCT "email" FROM "User" WHERE "organizationId"=$1 AND "role"::text IN ('ADMINISTRATOR','CEO') AND COALESCE("email",'')<>''`,organizationId).catch(()=>[]);const emails=[...new Set(rows.map(row=>clean(row.email,320).toLowerCase()).filter(Boolean))];if(!emails.length&&process.env.SMTP_USER)emails.push(process.env.SMTP_USER.trim().toLowerCase());return emails}
async function sendOwnerApprovalEmail(prisma:PrismaClient,ticket:QueueRow,triage:TriageResult,approvalId:string){
  const host=process.env.SMTP_HOST,user=process.env.SMTP_USER,pass=process.env.SMTP_PASS,port=Number(process.env.SMTP_PORT||587);if(!host||!user||!pass)return false;const recipients=await ownerRecipients(prisma,ticket.organizationId);if(!recipients.length)return false;const transporter=nodemailer.createTransport({host,port,secure:port===465,auth:{user,pass},connectionTimeout:10000,greetingTimeout:10000,socketTimeout:20000});const link=`https://www.sulandrahealth.com/it-solutions.html?ticket=${encodeURIComponent(ticket.ticketNumber)}#approvals`;const subject=`Approval required — ${ticket.ticketNumber} — ${clean(triage.summary,140)}`;const text=`Sulandra IT Specialist needs your decision.\n\nTicket: ${ticket.ticketNumber}\nProblem: ${triage.diagnosis}\nProposed major change: ${triage.request}\nTarget: ${triage.target}\nRisk: ${triage.risk}\nWhy approval is required: ${triage.reason}\n\nApproval record: ${approvalId}\nOpen IT Solutions: ${link}\n\nIn IT Solutions, enter ticket ${ticket.ticketNumber} and choose Approve, Request modification, or Decline.`;await transporter.sendMail({from:{name:'Sulandra Health IT Solutions',address:(process.env.FROM_EMAIL||process.env.SMTP_FROM||user).trim()},to:recipients,subject,text});return true
}

async function prepareEngineeringAction(prisma:PrismaClient,ticket:QueueRow,triage:TriageResult,requiresOwner:boolean){
  const existing=await prisma.$queryRawUnsafe<any[]>(`SELECT * FROM "ITRemediationApproval" WHERE "organizationId"=$1 AND "ticketId"=$2 AND "actionType"='CODE_CHANGE' AND "status" IN ('PENDING','APPROVED') ORDER BY "createdAt" DESC LIMIT 1`,ticket.organizationId,ticket.ticketId);if(existing[0])return existing[0];
  const actor=await systemActor(prisma,ticket.organizationId,ticket.employeeId),approvalId=randomUUID(),actionId=randomUUID(),handoffId=randomUUID();const status=requiresOwner?'PENDING':'APPROVED';
  await prisma.$executeRawUnsafe(`INSERT INTO "ITRemediationApproval" ("id","organizationId","ticketId","requestedByUserId","actionType","summary","risk","changeClass","requiresApproval","status","decidedByUserId","decisionNote","decidedAt") VALUES ($1,$2,$3,$4,'CODE_CHANGE',$5,$6,$7,$8,$9,$10,$11,CASE WHEN $8=FALSE THEN NOW() ELSE NULL END)`,approvalId,ticket.organizationId,ticket.ticketId,actor,triage.summary,triage.risk,requiresOwner?'NEW_SYSTEM_CHANGE':'ESTABLISHED_OPERATION_REPAIR',requiresOwner,status,requiresOwner?null:actor,requiresOwner?'':'Autonomous repair of an already-approved operation; owner approval not required by policy.');
  const result={ticketId:ticket.ticketId,ticketNumber:ticket.ticketNumber,approvalId};const payload={toolName:'request_code_change',summary:triage.summary,request:triage.request,target:triage.target,reason:triage.reason};await prisma.$executeRawUnsafe(`INSERT INTO "ITAgentAction" ("id","organizationId","conversationId","requestedByUserId","actionType","status","risk","changeClass","approvalRequired","summary","payload","result") VALUES ($1,$2,$3,$4,'REQUEST_CODE_CHANGE',$5,$6,$7,$8,$9,$10::jsonb,$11::jsonb)`,actionId,ticket.organizationId,ticket.conversationId||randomUUID(),ticket.employeeId,requiresOwner?'WAITING_APPROVAL':'PROPOSED',triage.risk,requiresOwner?'NEW_SYSTEM_CHANGE':'ESTABLISHED_OPERATION_REPAIR',requiresOwner,triage.summary,JSON.stringify(payload),JSON.stringify(result));
  await prisma.$executeRawUnsafe(`INSERT INTO "ITAgentHandoff" ("id","organizationId","ticketId","conversationId","employeeId","diagnosis","engineeringNeed","changeClass","status") VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9) ON CONFLICT ("organizationId","ticketId") DO UPDATE SET "diagnosis"=EXCLUDED."diagnosis","engineeringNeed"=EXCLUDED."engineeringNeed","changeClass"=EXCLUDED."changeClass","status"=EXCLUDED."status","updatedAt"=NOW()`,handoffId,ticket.organizationId,ticket.ticketId,ticket.conversationId||'',ticket.employeeId,triage.diagnosis,triage.engineeringNeed,requiresOwner?'NEW_SYSTEM_CHANGE':'ESTABLISHED_OPERATION_REPAIR',requiresOwner?'WAITING_APPROVAL':'IN_PROGRESS');
  await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "approvalId"=$1,"updatedAt"=NOW() WHERE "organizationId"=$2 AND "ticketId"=$3`,approvalId,ticket.organizationId,ticket.ticketId);return{id:approvalId,status,requiresApproval:requiresOwner}
}

async function resolveTicket(prisma:PrismaClient,ticket:QueueRow,resolution:string){const text=redact(resolution);await prisma.$executeRawUnsafe(`UPDATE "EmployeeSupportRequest" SET "status"='RESOLVED',"resolution"=$1,"resolvedAt"=COALESCE("resolvedAt",NOW()),"updatedAt"=NOW() WHERE "organizationId"=$2 AND "id"=$3`,text,ticket.organizationId,ticket.ticketId);await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "phase"='RESOLVED',"nextRunAt"=NULL,"leaseUntil"=NULL,"phaseStartedAt"=NOW(),"updatedAt"=NOW() WHERE "organizationId"=$1 AND "ticketId"=$2`,ticket.organizationId,ticket.ticketId);await prisma.$executeRawUnsafe(`UPDATE "ITTicketConversationBridge" SET "state"='RESOLVED',"heartbeatAt"=NOW(),"updatedAt"=NOW() WHERE "organizationId"=$1 AND "ticketId"=$2`,ticket.organizationId,ticket.ticketId);await prisma.$executeRawUnsafe(`UPDATE "ITAgentHandoff" SET "status"='RESOLVED',"resolution"=$1,"resolvedAt"=NOW(),"updatedAt"=NOW() WHERE "organizationId"=$2 AND "ticketId"=$3`,text,ticket.organizationId,ticket.ticketId).catch(()=>{});await postEmployeeUpdate(prisma,ticket,`${text}\n\nTicket ${ticket.ticketNumber} is resolved. If the same problem returns, tell SIA this ticket number so Sulandra IT can immediately correlate the history.`,'RESOLVED')}

async function processPending(prisma:PrismaClient,ticket:QueueRow){
  if(!enabled())return;const triage=await triageTicket(prisma,ticket);await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "classification"=$1,"diagnosis"=$2,"ownerNote"='',"updatedAt"=NOW() WHERE "organizationId"=$3 AND "ticketId"=$4`,triage.classification,triage.diagnosis,ticket.organizationId,ticket.ticketId);ticket.classification=triage.classification;ticket.diagnosis=triage.diagnosis;
  if(triage.classification==='RESOLVED_CONFIRMATION')return resolveTicket(prisma,ticket,triage.employeeMessage||'The employee confirmed the issue is resolved.');
  if(triage.needsEmployeeInput){const guide=await createVisualGuide(prisma,ticket,triage.visualGuide);await postEmployeeUpdate(prisma,ticket,`${triage.employeeQuestion||triage.employeeMessage}${guide?`\n\nVisual guide: ${guide.url}`:''}\n\nReply in Ask SIA and include ${ticket.ticketNumber}; the IT Specialist will continue from this exact point.`,'WAITING_EMPLOYEE');await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "phase"='WAITING_EMPLOYEE',"nextRunAt"=NULL,"leaseUntil"=NULL,"phaseStartedAt"=NOW(),"updatedAt"=NOW() WHERE "organizationId"=$1 AND "ticketId"=$2`,ticket.organizationId,ticket.ticketId);return}
  if(triage.classification==='SUPPORT_GUIDANCE'){const guide=await createVisualGuide(prisma,ticket,triage.visualGuide);await postEmployeeUpdate(prisma,ticket,`${triage.employeeMessage}${guide?`\n\nVisual click guide: ${guide.url}`:''}\n\nTry those steps now. Then reply in Ask SIA with ${ticket.ticketNumber} and tell me whether it worked. The ticket stays open until you confirm the result.`,'GUIDANCE_SENT');await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "phase"='FOLLOW_UP',"nextRunAt"=NOW()+INTERVAL '4 hours',"leaseUntil"=NULL,"phaseStartedAt"=NOW(),"updatedAt"=NOW() WHERE "organizationId"=$1 AND "ticketId"=$2`,ticket.organizationId,ticket.ticketId);return}
  if(triage.classification==='RESTRICTED_HUMAN'){await postEmployeeUpdate(prisma,ticket,`${triage.employeeMessage||'This ticket involves information or authority the automated IT Specialist will not handle directly.'}\n\nTicket ${ticket.ticketNumber} remains open and has been escalated safely.`,'ESCALATED');await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "phase"='WAITING_OWNER',"nextRunAt"=NULL,"leaseUntil"=NULL,"phaseStartedAt"=NOW(),"updatedAt"=NOW() WHERE "organizationId"=$1 AND "ticketId"=$2`,ticket.organizationId,ticket.ticketId);return}
  if(!['CODE_PATCH','CONFIG_REPAIR','DEPLOYMENT_REPAIR'].includes(triage.engineeringNeed)){triage.classification='MAJOR_CHANGE';triage.reason=`${triage.reason} Automated data repair is not permitted.`}
  const major=triage.classification==='MAJOR_CHANGE';const approval=await prepareEngineeringAction(prisma,ticket,triage,major);ticket.approvalId=approval.id;
  if(major){await postEmployeeUpdate(prisma,ticket,`I confirmed ${ticket.ticketNumber} needs a major or materially new system change. I sent the owner an approval request and preserved the full diagnosis. I will keep this ticket active while the decision is pending.`,'WAITING_APPROVAL');await sendOwnerApprovalEmail(prisma,ticket,triage,approval.id).catch(()=>false);await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "phase"='WAITING_OWNER',"approvalId"=$1,"nextRunAt"=NULL,"leaseUntil"=NULL,"phaseStartedAt"=NOW(),"updatedAt"=NOW() WHERE "organizationId"=$2 AND "ticketId"=$3`,approval.id,ticket.organizationId,ticket.ticketId);return}
  if(!autoProduction()){await postEmployeeUpdate(prisma,ticket,`I confirmed ${ticket.ticketNumber} is an established-operation repair, but automatic production promotion is currently disabled. The repair is queued without losing the ticket context.`,'QUEUED');await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "phase"='WAITING_OWNER',"approvalId"=$1,"nextRunAt"=NULL,"leaseUntil"=NULL,"phaseStartedAt"=NOW(),"updatedAt"=NOW() WHERE "organizationId"=$2 AND "ticketId"=$3`,approval.id,ticket.organizationId,ticket.ticketId);return}
  await postEmployeeUpdate(prisma,ticket,`I confirmed ${ticket.ticketNumber} is a regression of already-approved Sulandra behavior. I am repairing it under the established-operation policy now. No owner approval is required. I will test it before production and keep updating this SIA ticket.`,'IN_PROGRESS');const worker=await runApprovedITCodingWorker(prisma,{organizationId:ticket.organizationId,approvalId:approval.id,actorUserId:await systemActor(prisma,ticket.organizationId,ticket.employeeId)});await prisma.$executeRawUnsafe(`INSERT INTO "ITSpecialistProductionRun" ("id","organizationId","ticketId","ticketNumber","prNumber","headSha","status") VALUES ($1,$2,$3,$4,$5,$6,'WAITING_CI')`,randomUUID(),ticket.organizationId,ticket.ticketId,ticket.ticketNumber,worker.prNumber,worker.commitSha);await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "phase"='WAITING_CI',"prNumber"=$1,"prUrl"=$2,"headSha"=$3,"repairAttempts"="repairAttempts"+1,"nextRunAt"=NOW()+INTERVAL '45 seconds',"leaseUntil"=NULL,"phaseStartedAt"=NOW(),"updatedAt"=NOW() WHERE "organizationId"=$4 AND "ticketId"=$5`,worker.prNumber,worker.prUrl,worker.commitSha,ticket.organizationId,ticket.ticketId);await postEmployeeUpdate(prisma,{...ticket,prNumber:worker.prNumber,prUrl:worker.prUrl,headSha:worker.commitSha},`Repair code for ${ticket.ticketNumber} is prepared in PR #${worker.prNumber}. Required CI, Disaster Recovery, and Production Role UAT gates are running. I will not promote it unless those gates pass.`,'WAITING_CI')
}

async function processWaitingCi(prisma:PrismaClient,ticket:QueueRow){if(!ticket.headSha||!ticket.prNumber)throw httpError(409,'IT Specialist CI state is missing the PR head');const gates=await getITSpecialistGateState(ticket.headSha);await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistProductionRun" SET "gateEvidence"=$1::jsonb,"updatedAt"=NOW() WHERE "organizationId"=$2 AND "ticketId"=$3 AND "headSha"=$4`,JSON.stringify(gates),ticket.organizationId,ticket.ticketId,ticket.headSha).catch(()=>{});if(gates.state==='PENDING'){await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "nextRunAt"=NOW()+INTERVAL '60 seconds',"leaseUntil"=NULL,"updatedAt"=NOW() WHERE "organizationId"=$1 AND "ticketId"=$2`,ticket.organizationId,ticket.ticketId);return}if(gates.state==='FAILED'){await postEmployeeUpdate(prisma,ticket,`The automated repair for ${ticket.ticketNumber} did not pass its required validation (${gates.reason}). I stopped production promotion. The ticket is still active and has been escalated for a safer revised plan instead of pushing a failing change.`,'VALIDATION_FAILED');await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "phase"='PENDING',"ownerNote"=$1,"nextRunAt"=NOW()+INTERVAL '30 seconds',"leaseUntil"=NULL,"phaseStartedAt"=NOW(),"updatedAt"=NOW() WHERE "organizationId"=$2 AND "ticketId"=$3`,`Previous autonomous repair PR #${ticket.prNumber} failed required validation: ${gates.reason}. Reassess safely; do not weaken tests.`,ticket.organizationId,ticket.ticketId);return}const merged=await mergeITSpecialistPullRequest(ticket.prNumber,ticket.headSha,ticket.ticketNumber);await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistProductionRun" SET "mergeSha"=$1,"status"='DEPLOYING',"updatedAt"=NOW() WHERE "organizationId"=$2 AND "ticketId"=$3 AND "headSha"=$4`,merged.mergeSha,ticket.organizationId,ticket.ticketId,ticket.headSha);await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "phase"='DEPLOYING',"mergeSha"=$1,"nextRunAt"=NOW()+INTERVAL '30 seconds',"leaseUntil"=NULL,"phaseStartedAt"=NOW(),"updatedAt"=NOW() WHERE "organizationId"=$2 AND "ticketId"=$3`,merged.mergeSha,ticket.organizationId,ticket.ticketId);await postEmployeeUpdate(prisma,{...ticket,mergeSha:merged.mergeSha},`All required gates passed for ${ticket.ticketNumber}. The repair has been merged to the approved production line. I am now verifying the exact merged commit on the Static Website and both backend services before I call the ticket resolved.`,'DEPLOYING')}

async function processDeploying(prisma:PrismaClient,ticket:QueueRow){if(!ticket.mergeSha)throw httpError(409,'IT Specialist deployment state is missing the merge SHA');const verification=await verifyITSpecialistProductionCommit(ticket.mergeSha);await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistProductionRun" SET "productionEvidence"=$1::jsonb,"status"=$2,"updatedAt"=NOW() WHERE "organizationId"=$3 AND "ticketId"=$4 AND "mergeSha"=$5`,JSON.stringify(verification),verification.state==='GREEN'?'PRODUCTION_GREEN':'DEPLOYING',ticket.organizationId,ticket.ticketId,ticket.mergeSha).catch(()=>{});if(verification.state==='GREEN'){await syncITSpecialistKnowledge(prisma,true).catch(()=>null);return resolveTicket(prisma,ticket,`Sulandra IT restored the approved operation and verified the exact production commit ${ticket.mergeSha.slice(0,12)} on the Static Website and both backend services.`)}const started=new Date(ticket.phaseStartedAt).getTime();if(Date.now()-started>20*60*1000){await postEmployeeUpdate(prisma,ticket,`Production verification for ${ticket.ticketNumber} did not converge on all three services within the safety window. I am not declaring success. The ticket remains active and is escalated with the deployment evidence.`,'DEPLOYMENT_VERIFY_FAILED');await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "phase"='WAITING_OWNER',"nextRunAt"=NULL,"leaseUntil"=NULL,"lastError"='Production verification timeout',"updatedAt"=NOW() WHERE "organizationId"=$1 AND "ticketId"=$2`,ticket.organizationId,ticket.ticketId);return}await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "nextRunAt"=NOW()+INTERVAL '45 seconds',"leaseUntil"=NULL,"updatedAt"=NOW() WHERE "organizationId"=$1 AND "ticketId"=$2`,ticket.organizationId,ticket.ticketId)}

async function processFollowUp(prisma:PrismaClient,ticket:QueueRow){await postEmployeeUpdate(prisma,ticket,`Ticket ${ticket.ticketNumber} is still open. If the guidance fixed the problem, tell Ask SIA “${ticket.ticketNumber} is fixed.” If it did not, tell SIA what happened after the last step and Sulandra IT will continue from the existing ticket.`,'WAITING_EMPLOYEE');await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "phase"='WAITING_EMPLOYEE',"nextRunAt"=NULL,"leaseUntil"=NULL,"phaseStartedAt"=NOW(),"updatedAt"=NOW() WHERE "organizationId"=$1 AND "ticketId"=$2`,ticket.organizationId,ticket.ticketId)}

async function claimNext(prisma:PrismaClient){await ensureITSpecialistSchema(prisma);await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "leaseUntil"=NULL,"updatedAt"=NOW() WHERE "leaseUntil"<NOW() AND "phase" NOT IN ('RESOLVED','DECLINED','WAITING_OWNER','WAITING_EMPLOYEE')`).catch(()=>{});const rows=await prisma.$queryRawUnsafe<QueueRow[]>(`WITH candidate AS (SELECT "id" FROM "ITSpecialistQueue" WHERE "phase" IN ('PENDING','OWNER_APPROVED','WAITING_CI','DEPLOYING','FOLLOW_UP') AND COALESCE("nextRunAt",NOW())<=NOW() AND ("leaseUntil" IS NULL OR "leaseUntil"<NOW()) ORDER BY "updatedAt" ASC FOR UPDATE SKIP LOCKED LIMIT 1) UPDATE "ITSpecialistQueue" q SET "leaseUntil"=NOW()+INTERVAL '10 minutes',"updatedAt"=NOW() FROM candidate c WHERE q."id"=c."id" RETURNING q.*`);return rows[0]||null}

async function workOnce(prisma:PrismaClient){if(!enabled())return false;const ticket=await claimNext(prisma);if(!ticket)return false;try{if(ticket.phase==='PENDING')await processPending(prisma,ticket);else if(ticket.phase==='OWNER_APPROVED'){if(!ticket.approvalId)throw httpError(409,'Owner-approved ticket has no approval record');await postEmployeeUpdate(prisma,ticket,`Owner approval was received for ${ticket.ticketNumber}. I am implementing the approved change now and will continue through validation and exact production verification.`,'IN_PROGRESS');const worker=await runApprovedITCodingWorker(prisma,{organizationId:ticket.organizationId,approvalId:ticket.approvalId,actorUserId:await systemActor(prisma,ticket.organizationId,ticket.employeeId)});await prisma.$executeRawUnsafe(`INSERT INTO "ITSpecialistProductionRun" ("id","organizationId","ticketId","ticketNumber","prNumber","headSha","status") VALUES ($1,$2,$3,$4,$5,$6,'WAITING_CI')`,randomUUID(),ticket.organizationId,ticket.ticketId,ticket.ticketNumber,worker.prNumber,worker.commitSha);await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "phase"='WAITING_CI',"prNumber"=$1,"prUrl"=$2,"headSha"=$3,"nextRunAt"=NOW()+INTERVAL '45 seconds',"leaseUntil"=NULL,"phaseStartedAt"=NOW(),"updatedAt"=NOW() WHERE "organizationId"=$4 AND "ticketId"=$5`,worker.prNumber,worker.prUrl,worker.commitSha,ticket.organizationId,ticket.ticketId)}else if(ticket.phase==='WAITING_CI')await processWaitingCi(prisma,ticket);else if(ticket.phase==='DEPLOYING')await processDeploying(prisma,ticket);else if(ticket.phase==='FOLLOW_UP')await processFollowUp(prisma,ticket);return true}catch(error){const message=redact(error instanceof Error?error.message:error);await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "leaseUntil"=NULL,"lastError"=$1,"nextRunAt"=NOW()+INTERVAL '2 minutes',"updatedAt"=NOW() WHERE "organizationId"=$2 AND "ticketId"=$3`,message,ticket.organizationId,ticket.ticketId).catch(()=>{});await postEmployeeUpdate(prisma,ticket,`Sulandra IT is still working on ${ticket.ticketNumber}. An automated step encountered a recoverable problem and has been queued to retry. The ticket and conversation context remain active; you do not need to start over.`,'RETRYING').catch(()=>{});return false}}

export function registerITSpecialistAutonomyRoutes({app,prisma,authOf,requireRoles,adminRoles}:Dependencies){
  const admin=requireRoles(...adminRoles),all=requireRoles(...(Object.values(require('@prisma/client').UserRole) as UserRole[]));let readyPromise:Promise<void>|null=null;const ready=()=>readyPromise??=ensureITSpecialistSchema(prisma).catch(error=>{readyPromise=null;throw error});
  app.get('/api/it-solutions/specialist/status',admin,async(_req,res,next)=>{try{await ready();const queue=await prisma.$queryRawUnsafe<any[]>(`SELECT "phase",COUNT(*)::int AS count FROM "ITSpecialistQueue" GROUP BY "phase"`);const knowledge=await syncITSpecialistKnowledge(prisma,false);res.json({data:{...itSpecialistKnowledgeStatus(),model:model(),queue,knowledge}})}catch(error){next(error)}});
  app.post('/api/it-solutions/specialist/knowledge/sync',admin,async(_req,res,next)=>{try{await ready();res.json({data:await syncITSpecialistKnowledge(prisma,true)})}catch(error){next(error)}});
  app.get('/api/it-solutions/specialist/tickets/:ticketNumber',all,async(req,res,next)=>{try{await ready();const auth=authOf(res);const rows=await prisma.$queryRawUnsafe<any[]>(`SELECT q.*,r."subject",r."category",r."priority",r."status" AS "requestStatus",r."resolution" FROM "ITSpecialistQueue" q JOIN "EmployeeSupportRequest" r ON r."organizationId"=q."organizationId" AND r."id"=q."ticketId" WHERE q."organizationId"=$1 AND LOWER(q."ticketNumber")=LOWER($2) AND (q."employeeId"=$3 OR $4::boolean=TRUE) LIMIT 1`,auth.organizationId,req.params.ticketNumber,auth.userId,adminRoles.includes(auth.role));if(!rows[0])return void res.status(404).json({error:'IT ticket was not found'});const updates=await prisma.$queryRawUnsafe<any[]>(`SELECT "message","status","createdAt" FROM "ITEmployeeUpdate" WHERE "organizationId"=$1 AND "ticketId"=$2 ORDER BY "createdAt" ASC LIMIT 200`,auth.organizationId,rows[0].ticketId).catch(()=>[]);res.json({data:{ticket:rows[0],updates}})}catch(error){next(error)}});
  app.get('/api/it-solutions/employee/guides/:guideId',all,async(req,res,next)=>{try{await ready();const auth=authOf(res);const rows=await prisma.$queryRawUnsafe<any[]>(`SELECT * FROM "ITVisualGuide" WHERE "organizationId"=$1 AND "id"=$2 AND ("employeeId"=$3 OR $4::boolean=TRUE) LIMIT 1`,auth.organizationId,req.params.guideId,auth.userId,adminRoles.includes(auth.role));if(!rows[0])return void res.status(404).json({error:'Visual guide was not found'});res.json({data:{guide:rows[0]}})}catch(error){next(error)}});
  app.post('/api/it-solutions/specialist/owner-decision',admin,async(req,res,next)=>{try{await ready();const auth=authOf(res),input=decisionSchema.parse(req.body);const rows=await prisma.$queryRawUnsafe<QueueRow[]>(`SELECT * FROM "ITSpecialistQueue" WHERE "organizationId"=$1 AND LOWER("ticketNumber")=LOWER($2) LIMIT 1`,auth.organizationId,input.ticketNumber),ticket=rows[0];if(!ticket)throw httpError(404,'IT ticket number was not found');const approvals=await prisma.$queryRawUnsafe<any[]>(`SELECT * FROM "ITRemediationApproval" WHERE "organizationId"=$1 AND "ticketId"=$2 AND "status" IN ('PENDING','MODIFICATION_REQUESTED') ORDER BY "createdAt" DESC LIMIT 1`,auth.organizationId,ticket.ticketId),approval=approvals[0];if(!approval)throw httpError(409,'This ticket has no pending major-change approval');if(input.decision==='APPROVE'){await prisma.$executeRawUnsafe(`UPDATE "ITRemediationApproval" SET "status"='APPROVED',"decidedByUserId"=$1,"decisionNote"=$2,"decidedAt"=NOW(),"updatedAt"=NOW() WHERE "id"=$3`,auth.userId,input.note,approval.id);await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "phase"='OWNER_APPROVED',"approvalId"=$1,"ownerNote"=$2,"nextRunAt"=NOW(),"leaseUntil"=NULL,"phaseStartedAt"=NOW(),"updatedAt"=NOW() WHERE "id"=$3`,approval.id,input.note,ticket.id);await postEmployeeUpdate(prisma,ticket,`Owner approval was received for ${ticket.ticketNumber}. Sulandra IT is continuing the approved change.`,'OWNER_APPROVED')}else if(input.decision==='MODIFY'){await prisma.$executeRawUnsafe(`UPDATE "ITRemediationApproval" SET "status"='MODIFICATION_REQUESTED',"decidedByUserId"=$1,"decisionNote"=$2,"decidedAt"=NOW(),"updatedAt"=NOW() WHERE "id"=$3`,auth.userId,input.note,approval.id);await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "phase"='PENDING',"approvalId"=NULL,"ownerNote"=$1,"nextRunAt"=NOW(),"leaseUntil"=NULL,"phaseStartedAt"=NOW(),"updatedAt"=NOW() WHERE "id"=$2`,input.note,ticket.id);await postEmployeeUpdate(prisma,ticket,`The owner requested a modification to the proposed solution for ${ticket.ticketNumber}. Sulandra IT is revising the plan while keeping the ticket active.`,'MODIFICATION_REQUESTED')}else{await prisma.$executeRawUnsafe(`UPDATE "ITRemediationApproval" SET "status"='DENIED',"decidedByUserId"=$1,"decisionNote"=$2,"decidedAt"=NOW(),"updatedAt"=NOW() WHERE "id"=$3`,auth.userId,input.note,approval.id);await prisma.$executeRawUnsafe(`UPDATE "ITSpecialistQueue" SET "phase"='DECLINED',"nextRunAt"=NULL,"leaseUntil"=NULL,"ownerNote"=$1,"updatedAt"=NOW() WHERE "id"=$2`,input.note,ticket.id);await prisma.$executeRawUnsafe(`UPDATE "EmployeeSupportRequest" SET "status"='CLOSED',"resolution"=$1,"resolvedAt"=NOW(),"updatedAt"=NOW() WHERE "organizationId"=$2 AND "id"=$3`,`Owner declined the proposed major change. ${input.note}`,ticket.organizationId,ticket.ticketId);await postEmployeeUpdate(prisma,ticket,`The proposed major change for ${ticket.ticketNumber} was declined. No production change was made. ${input.note?`Owner note: ${input.note}`:''}`,'DECLINED')}res.json({data:{ticketNumber:ticket.ticketNumber,decision:input.decision}})}catch(error){next(error)}});
  app.post('/api/it-solutions/specialist/process-once',admin,async(_req,res,next)=>{try{await ready();res.json({data:{processed:await workOnce(prisma)}})}catch(error){next(error)}});
  if(enabled()){void ready().then(()=>syncITSpecialistKnowledge(prisma,false)).catch(()=>{});const timer=setInterval(()=>void workOnce(prisma),15000);timer.unref();setTimeout(()=>void workOnce(prisma),2500).unref()}
}
